// Package money handles amounts of money. An amount is an int64 count of its currency's minor unit (cents for USD, yen for
// JPY, fils for KWD), never a float.
package money

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Currency is an ISO 4217 currency code.
type Currency string

// The currencies Tally bills in.
const (
	USD Currency = "USD"
	EUR Currency = "EUR"
	GBP Currency = "GBP"
	JPY Currency = "JPY"
	KWD Currency = "KWD"
)

// currencies holds what each currency looks like: its symbol for people (KWD has none, so it is written out) and how many
// decimal places its major unit has (ISO 4217's minor unit exponent).
var currencies = map[Currency]struct {
	symbol     string
	minorUnits int
}{
	USD: {"$", 2},
	EUR: {"€", 2},
	GBP: {"£", 2},
	JPY: {"¥", 0},
	KWD: {"KWD ", 3},
}

// Valid reports whether c is a currency Tally bills in.
func (c Currency) Valid() bool {
	_, ok := currencies[c]
	return ok
}

// MinorUnits returns how many decimal places c's major unit has: 2 for USD, 0 for JPY, 3 for KWD. It is 0 for a currency
// Tally does not bill in; check Valid first.
func (c Currency) MinorUnits() int { return currencies[c].minorUnits }

// ErrInvalidAmount is returned for an amount that cannot be read.
var ErrInvalidAmount = errors.New("invalid amount")

// ParseMajor reads an amount a person typed in major units ("12.50", "7") and returns it in minor units. It takes at most
// the currency's decimal places and pads fewer: "12.5" USD is 1250, "7" KWD is 7000. JPY takes no decimal point at all.
func ParseMajor(s string, c Currency) (int64, error) {
	if !c.Valid() {
		return 0, fmt.Errorf("%w: unknown currency %q", ErrInvalidAmount, c)
	}
	s = strings.TrimSpace(s)
	decimals := c.MinorUnits()
	whole, frac, hasDot := strings.Cut(s, ".")
	if whole == "" || (hasDot && frac == "") || len(frac) > decimals {
		return 0, fmt.Errorf("%w: %q has more than %d decimal places for %s", ErrInvalidAmount, s, decimals, c)
	}
	for _, r := range whole + frac {
		if r < '0' || r > '9' {
			return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
		}
	}
	for len(frac) < decimals {
		frac += "0"
	}
	n, err := strconv.ParseInt(whole+frac, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	return n, nil
}

// Format renders an amount for people, with the currency's decimal places: "$1,234.50", "€0.99", "¥1,000", "KWD 1.250",
// "-$5.00".
func Format(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	return sign + currencies[c].symbol + group(whole) + frac
}

// FormatMajor renders an amount in major units with the currency's decimal places and no thousands separator or symbol:
// "12.50", "1000", "1.250", "-5.00".
func FormatMajor(amount int64, c Currency) string {
	sign, whole, frac := split(amount, c)
	return sign + whole + frac
}

// split separates an amount into its sign, its whole major units and its fraction (".50", or "" for no decimals).
func split(amount int64, c Currency) (sign, whole, frac string) {
	u := uint64(amount)
	if amount < 0 {
		sign, u = "-", -u // also right for the most negative amount
	}
	decimals := c.MinorUnits()
	scale := uint64(1)
	for i := 0; i < decimals; i++ {
		scale *= 10
	}
	whole = strconv.FormatUint(u/scale, 10)
	if decimals > 0 {
		frac = fmt.Sprintf(".%0*d", decimals, u%scale)
	}
	return sign, whole, frac
}

// group writes the digits of a whole amount with a comma between each group of three.
func group(digits string) string {
	var b strings.Builder
	for i, r := range digits {
		if i > 0 && (len(digits)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(r)
	}
	return b.String()
}
EOF
